cups_file_t * cupsdOpenConfFile ( const char * filename ) { cups_file_t * fp ; if ( ( fp = cupsFileOpen ( filename , "r" ) ) == NULL ) { if ( errno == ENOENT ) { char oldfile [ 1024 ] ; sprintf ( oldfile , "%s.O" , filename ) ; fp = cupsFileOpen ( oldfile , "r" ) ; } else { cupsdLogMessage ( CUPSD_LOG_ERROR , "Unable to open \"%s\": %s" , filename , strerror ( errno ) ) ; } } return ( fp ) ; } 